select * from (
    select A.*,M.MACHINE_NAME from t_tm_quota_setting A LEFT JOIN T_TM_MACHINE_INFO M
    ON A.machine_id=M.ID
    WHERE A.del_flag='0'
    and INSTR(A.tread_code, #{treadCode,jdbcType=VARCHAR}) > 0
    and A.machine_id = #{machineId,jdbcType=DECIMAL}
    order by A.create_time desc
)

